urlset:

    https://yenisozcukler.com/
    {% if latest_word %}{{ latest_word.timestamp|date:"c" }}{% endif %}
    daily
    1.0

{% for category in categories %}

    https://yenisozcukler.com/kategori/{{ category.slug }}/
    weekly
    0.7

{% endfor %}
{% for word in words %}

    https://yenisozcukler.com/sozcuk/{{ word.slug }}/
    {{ word.timestamp|date:"c" }}
    monthly
    0.8

{% endfor %}
